gcode_macro smart_park.gcode:
{% set kamp_settings = printer["gcode_macro _KAMP_Settings"] %}
{% set z_height = kamp_settings.smart_park_height | float %}
{% set purge_margin = kamp_settings.purge_margin | float %}
{% set verbose_enable = kamp_settings.verbose_enable | abs %}
{% set center_x = printer.toolhead.axis_maximum.x / 2 | float %}
{% set center_y = printer.toolhead.axis_maximum.y / 2 | float %}
{% set axis_minimum_x = printer.toolhead.axis_minimum.x | float %}
{% set axis_minimum_y = printer.toolhead.axis_minimum.y | float %}
{% set all_points = printer.exclude_object.objects | map(attribute='polygon') | sum(start=[]) %}
{% set x_min = all_points | map(attribute=0) | min | default(center_x) %}
{% set y_min = all_points | map(attribute=1) | min | default(center_y) %}
{% set travel_speed = (printer.toolhead.max_velocity) * 60 | float %}

{% if purge_margin > 0 and x_min != center_x and y_min != center_y %}
{% set x_min = [ x_min - purge_margin , x_min ] | min %}
{% set y_min = [ y_min - purge_margin , y_min ] | min %}
{% set x_min = [ x_min , axis_minimum_x ] | max %}
{% set y_min = [ y_min , axis_minimum_y ] | max %}
{% endif %}


{% if verbose_enable == True %}

{ action_respond_info("Smart Park location: {},{}.".format(
(x_min),
(y_min),
)) }

{% endif %}

SAVE_GCODE_STATE NAME=Presmartpark_State

G90
{% if printer.toolhead.position.z < z_height %}
G0 Z{z_height}
{% endif %}
G0 X{x_min} Y{y_min} F{travel_speed}
G0 Z{z_height}

RESTORE_GCODE_STATE NAME=Presmartpark_State

filament_switch_sensor switch_sensor.runout_gcode:
{% if printer.print_stats.state == "printing" %}
M117 Filament runout soon
RESPOND TYPE=echo MSG='Filament leaving sensor - runout expected soon'
RUN_SHELL_COMMAND CMD=text_to_speech PARAMS="Ender 5 Filament Runout"
{% endif %}

filament_motion_sensor encoder_sensor.runout_gcode:
{% if printer.print_stats.state == "printing" %}
{% set bowden = printer["gcode_macro _FILAMENT_SENSOR_CONFIG"].bowden_length %}
{% if printer["filament_switch_sensor switch_sensor"].filament_detected %}
RESPOND TYPE=error MSG='Filament jam/bind detected - pausing'
M117 Filament Bind
RUN_SHELL_COMMAND CMD=text_to_speech PARAMS="Ender 5 Filament Bind"
PAUSE
{% else %}
RESPOND TYPE=error MSG='Filament runout - pausing in {bowden}mm'
M117 Filament Runout
PAUSE_AFTER_D D={bowden}
{% endif %}
{% endif %}

gcode_macro pause_after_d.gcode:
{% set d_start = printer.print_stats.filament_used|float %}
{% set d_end = d_start + params.D|float %}
SET_GCODE_VARIABLE MACRO=PAUSE_AFTER_D VARIABLE=end_d VALUE={d_end}
RESPOND TYPE=echo MSG='Will pause after {params.D}mm more extrusion'
M117 Pause in {params.D}mm
UPDATE_DELAYED_GCODE ID=PAUSE_AT_D DURATION=1

delayed_gcode pause_at_d.gcode:
{% set end_d = printer["gcode_macro PAUSE_AFTER_D"].end_d %}
{% if end_d > 0 %}
{% if printer.print_stats.state == "printing" %}
{% set d_current = printer.print_stats.filament_used|float %}
{% set remaining = (end_d - d_current)|round(1) %}
{% if d_current < end_d %}
M117 Pause in {remaining}mm
UPDATE_DELAYED_GCODE ID=PAUSE_AT_D DURATION=1
{% else %}
RUN_SHELL_COMMAND CMD=text_to_speech PARAMS="Ender 5 Runout Complete"
PAUSE
SET_GCODE_VARIABLE MACRO=PAUSE_AFTER_D VARIABLE=end_d VALUE=0
{% endif %}
{% elif printer.print_stats.state == "paused" %}
UPDATE_DELAYED_GCODE ID=PAUSE_AT_D DURATION=2
{% else %}
SET_GCODE_VARIABLE MACRO=PAUSE_AFTER_D VARIABLE=end_d VALUE=0
{% endif %}
{% endif %}

gcode_macro get_timelapse_setup.gcode:
{% set tl = printer['gcode_macro TIMELAPSE_TAKE_FRAME'] %}
{% set output_txt = ["Timelapse Setup:"] %}
{% set _dummy = output_txt.append("enable: %s" % tl.enable) %}
{% set _dummy = output_txt.append("park: %s" % tl.park.enable) %}
{% if tl.park.enable %}
{% set _dummy = output_txt.append("park position: %s time: %s s" % (tl.park.pos, tl.park.time)) %}
{% set _dummy = output_txt.append("park cord x:%s y:%s dz:%s" % (tl.park.coord.x, tl.park.coord.y, tl.park.coord.dz)) %}
{% set _dummy = output_txt.append("travel speed: %s mm/s" % tl.speed.travel) %}
{% endif %}
{% set _dummy = output_txt.append("fw_retract: %s" % tl.extruder.fw_retract) %}
{% if not tl.extruder.fw_retract %}
{% set _dummy = output_txt.append("retract: %s mm speed: %s mm/s" % (tl.extruder.retract, tl.speed.retract)) %}
{% set _dummy = output_txt.append("extrude: %s mm speed: %s mm/s" % (tl.extruder.extrude, tl.speed.extrude)) %}
{% endif %}
{% set _dummy = output_txt.append("verbose: %s" % tl.verbose) %}
{action_respond_info(output_txt|join("\n"))}

gcode_macro _set_timelapse_setup.gcode:
{% set tl = printer['gcode_macro TIMELAPSE_TAKE_FRAME'] %}

{% set min = printer.toolhead.axis_minimum %}
{% set max = printer.toolhead.axis_maximum %}
{% set round_bed = True if printer.configfile.settings.printer.kinematics is in ['delta','polar','rotary_delta','winch']
else False %}
{% set park = {'min'   : {'x': (min.x / 1.42)|round(3) if round_bed else min.x|round(3),
