gcode_macro search_vars.gcode:
{% if not params.S %}
{action_respond_info("hmm.. try 'SEARCH_VARS s=\"profile\"'")}
{% else %}
{% set resultcount = namespace(total=0) %}
{% set search = params.S|lower %}
{% set ns = namespace() %}
{% for item in printer  %}
{% if ' ' in item %}
{% set ns.path = ['printer', "['%s']" % (item), ''] %}
{% else %}
{% set ns.path = ['printer.', item, ''] %}
{% endif %}

{% if search in ns.path|lower %}
{ action_respond_info(ns.path|join) }
{% set resultcount.total = 1 + resultcount.total %}
{% endif %}

{% if printer[item].items() %}
{% for childkey, child in printer[item].items() recursive %}
{% set ns.path = ns.path[:loop.depth|int + 1] %}

{% if ' ' in childkey %}
{% set null = ns.path.append("['%s']" % (childkey)) %}
{% else %}
{% set null = ns.path.append(".%s" % (childkey)) %}
{% endif %}

{% if child is mapping  %}
{ loop(child.items()) }
{% else %}
{% if search in ns.path|lower %}
{ action_respond_info("%s : %s" % (ns.path|join, child)) }
{% set resultcount.total = 1 + resultcount.total %}
{% endif %}
{% endif %}

{% endfor %}
{% endif %}
{% endfor %}
{% if resultcount.total >= 1 %}
{action_respond_info("found \"" + params.S + "\" " + resultcount.total|string +" times.")}
{% else %}
{action_respond_info("\"" + params.S + "\" not found.")}
{% endif %}
{% set resultcount.total = 0|int %}
{% endif %}

gcode_macro wait_for_enclosure_temp.gcode:
{% set target = params.TARGET|default(40)|float %}
{% set cur = printer['temperature_sensor combined_frame'].temperature|float %}
SET_GCODE_VARIABLE MACRO=WAIT_FOR_ENCLOSURE_TEMP VARIABLE=target VALUE={target}
UPDATE_DELAYED_GCODE ID=_enclosure_temp_poll DURATION=1
RESPOND TYPE=echo MSG="Waiting for enclosure to reach {target}C (currently {cur|round(1)}C)..."

delayed_gcode _enclosure_temp_poll.gcode:
{% set tgt = printer['gcode_macro WAIT_FOR_ENCLOSURE_TEMP'].target|float %}
{% set cur = printer['temperature_sensor combined_frame'].temperature|float %}
{% if cur >= tgt %}
RUN_SHELL_COMMAND CMD=text_to_speech PARAMS="Ender 5 Enclosure Temperature Reached"
RESPOND TYPE=echo MSG="combined_frame at {cur|round(1)}C (target {tgt}C) - notified."
{% else %}
UPDATE_DELAYED_GCODE ID=_enclosure_temp_poll DURATION=10
{% endif %}

gcode_macro g28.gcode:
{% set axes = 'XYZ'|select('in', params)|join() %}
{% set safe_z = printer["gcode_macro _User_Variables"].safe_z|default(10)|float %}
{% set enable_z_hop = printer["gcode_macro _User_Variables"].enable_z_hop|default(True) %}
{% set z_feedrate = printer["gcode_macro _User_Variables"].z_drop_speed|default(20)|float * 60 %}
{% set wants_z = not axes or 'Z' in axes %}
{% if enable_z_hop and 'z' not in printer.toolhead.homed_axes %}
SET_KINEMATIC_POSITION Z=0
G0 Z{safe_z} F{z_feedrate}
{% if not wants_z %}
M84
{% endif %}
{% elif enable_z_hop and printer.gcode_move.gcode_position.z < safe_z %}
G0 Z{safe_z} F{z_feedrate}
{% endif %}
G28.6245197{% for axis in axes %} {axis}{% endfor %}

